        if LXML:
            children = list(sec)
            paras = [c for c in children if localname(c.tag) == "p"]
        else:
            children = list(sec)
            paras = [c for c in children if localname(c.tag) == "p"]

        # Find heading paragraph exactly '후속 조치'
        heading_idx = None
        for idx, p in enumerate(paras):
            if paragraph_text(p).strip() == "후속 조치":
                heading_idx = idx
                break
        if heading_idx is None:
            continue

        # Collect consecutive numbered follow-up paragraphs after heading
        numbered = []
        for p in paras[heading_idx + 1 :]:
            txt = paragraph_text(p).strip()
            if re.match(r"^\d+\.\s+", txt):
                numbered.append(p)
                continue
            # stop at first non-numbered paragraph after we started
            if numbered:
                break

        if not numbered:
            continue

        formatted = [f"{seq}. {item}" for seq, item in followups_sorted]

        # Determine max id in this section to assign ids for new paragraphs
        def _parse_id(p):
            try:
                return int(p.get("id"))
            except Exception:
                return None

        existing_ids = [i for i in (_parse_id(p) for p in paras) if i is not None]
        next_id = (max(existing_ids) + 1) if existing_ids else 1

        # Replace existing paragraphs text for min(len)
        n_common = min(len(numbered), len(formatted))
        for i in range(n_common):
            p = numbered[i]
            if APPENDIX_SENTENCE in paragraph_text(p):
                continue
            if paragraph_text(p) != formatted[i]:
                set_paragraph_text_collapsed(p, formatted[i], root_for_parent_map=root)
                remove_lineseg_cache(p, root_for_parent_map=root)
                modified += 1

        # Remove extra old follow-ups
        if len(numbered) > len(formatted):
            for p in numbered[len(formatted) :]:
                if LXML:
                    sec.remove(p)
                else:
                    sec.remove(p)
                modified += 1

        # Add additional follow-ups
        if len(formatted) > len(numbered):
            template = numbered[-1]
            insert_after = numbered[-1]

            # Find actual index among section children to insert after
            child_list = list(sec)
            try:
                insert_pos = child_list.index(insert_after) + 1
            except ValueError:
                insert_pos = len(child_list)

            for txt in formatted[len(numbered) :]:
                new_p = copy.deepcopy(template)
                # Update id if present
                if new_p.get("id") is not None:
                    new_p.set("id", str(next_id))
                    next_id += 1
                set_paragraph_text_collapsed(new_p, txt, root_for_parent_map=root)
                remove_lineseg_cache(new_p, root_for_parent_map=root)
                sec.insert(insert_pos, new_p)
                insert_pos += 1
                modified += 1

    return modified


def verify_appendix_preserved(root):
    found = False
    for p in findall_paragraphs(root):
        if paragraph_text(p) == APPENDIX_SENTENCE:
            found = True
    return found


def process_contents_xml(xml_path: Path, update_data: dict, followups_sorted):
    root = parse_xml(xml_path)

    before_appendix_ok = verify_appendix_preserved(root)

    modified = 0
    modified += update_prefix_fields(root, update_data)
    modified += update_table_fields(root, update_data)
    modified += update_followups(root, followups_sorted)

    after_appendix_ok = verify_appendix_preserved(root)
    if before_appendix_ok and not after_appendix_ok:
