#!/usr/bin/env python3
"""Update a HWPX (zip-based) renewal playbook from JSON + CSV inputs.

Writes /root/renewal_playbook_updated.hwpx

Key behaviors (per task contract):
- Handle HWPX text fragmentation across multiple <hp:t> spans by concatenating
  paragraph text before matching, then collapsing to a single <hp:t> on edit.
- Replace field values (customer, owner, window, band, escalation, note).
- Replace follow-up lines from CSV (sorted by sequence).
- Preserve appendix sentence exactly: '이 부록 문단은 그대로 유지해야 합니다.'
- Remove lineSegArray / linesegarray cache elements ONLY from modified paragraphs.
"""

from __future__ import annotations

import copy
import csv
import json
import os
import re
import sys
import zipfile
from pathlib import Path

APPENDIX_SENTENCE = "이 부록 문단은 그대로 유지해야 합니다."

SRC_HWPX = Path("/root/renewal_playbook.hwpx")
OUT_HWPX = Path("/root/renewal_playbook_updated.hwpx")
WORK_DIR = Path("/root/hwpx_work")
UNPACK_DIR = WORK_DIR / "unpacked"
UPDATE_JSON = Path("/root/renewal_update.json")
FOLLOWUPS_CSV = Path("/root/followups.csv")

HWP_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
NSMAP = {"hp": HWP_NS}


def _try_import_lxml():
    try:
        from lxml import etree  # type: ignore

        return etree
    except Exception:
        return None


LXML = _try_import_lxml()


def localname(tag: str) -> str:
    """Return localname for '{ns}tag' or 'pfx:tag' or 'tag'."""
    if tag is None:
        return ""
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    if ":" in tag:
        return tag.split(":", 1)[1]
    return tag


def build_parent_map(root):
    """Build child->parent map (ElementTree compatibility)."""
    parent = {}
    for p in root.iter():
        for c in list(p):
            parent[c] = p
    return parent


def paragraph_text(p) -> str:
    parts = []
    for el in p.iter():
        if localname(getattr(el, "tag", "")) == "t":
            txt = getattr(el, "text", None)
            if txt:
                parts.append(txt)
    return "".join(parts)


def ensure_run_and_t(p, parent_map=None):
    """Ensure paragraph has at least one run and one t, return first t element."""
    # Find first run
    run = None
    for el in p.iter():
        if localname(getattr(el, "tag", "")) == "run":
            run = el
            break
    if run is None:
        # Create <hp:run><hp:t/></hp:run> under paragraph
        if LXML:
            run = LXML.Element(f"{{{HWP_NS}}}run")
            p.append(run)
        else:
            import xml.etree.ElementTree as ET

            run = ET.Element(f"{{{HWP_NS}}}run")
            p.append(run)

    # Find first t under the run (or anywhere)
    t0 = None
    for el in p.iter():
        if localname(getattr(el, "tag", "")) == "t":
            t0 = el
            break
    if t0 is None:
        if LXML:
            t0 = LXML.Element(f"{{{HWP_NS}}}t")
            run.append(t0)
        else:
            import xml.etree.ElementTree as ET

            t0 = ET.Element(f"{{{HWP_NS}}}t")
            run.append(t0)
    return t0


def set_paragraph_text_collapsed(p, new_text: str, root_for_parent_map=None):
    """Set paragraph text, collapsing multiple <t> nodes into one."""
    if LXML:
        t_elems = [el for el in p.iter() if localname(el.tag) == "t"]
        if not t_elems:
            t0 = ensure_run_and_t(p)
            t_elems = [t0]
        t_elems[0].text = new_text
        for extra in t_elems[1:]:
            parent = extra.getparent()
            if parent is not None:
                parent.remove(extra)
        return

    # ElementTree path
    import xml.etree.ElementTree as ET

    root = root_for_parent_map
    if root is None:
        raise ValueError("root_for_parent_map is required for ElementTree edits")
    parent_map = build_parent_map(root)

    t_elems = [el for el in p.iter() if localname(el.tag) == "t"]
    if not t_elems:
        t0 = ensure_run_and_t(p)
        parent_map = build_parent_map(root)  # refresh after insertion
        t_elems = [t0]

    t_elems[0].text = new_text
    for extra in t_elems[1:]:
        par = parent_map.get(extra)
        if par is not None:
            par.remove(extra)


def remove_lineseg_cache(p, root_for_parent_map=None):
    """Remove lineSegArray/linesegarray descendants from a paragraph."""
    target_lnames = {"linesegarray", "linesegarray".lower(), "linesegarray".upper(), "linesegarray"}
    # plus canonical camel-case
    target_lnames |= {"linesegarray", "lineSegArray".lower(), "linesegarray".lower()}

    def is_target(el):
        ln = localname(getattr(el, "tag", ""))
        return ln.lower() in {"linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "lineSegArray".lower(), "linesegarray".lower()} or ln.lower() in {"linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray"} or ln.lower() in {"linesegarray", "linesegarray"}  # keep simple below

    # We'll use a simpler check:
    def is_linesegarray(el):
        return localname(getattr(el, "tag", "")).lower() in {"linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray"} or localname(getattr(el, "tag", "")) in {"lineSegArray", "linesegarray"}

    if LXML:
        for el in list(p.iter()):
            if is_linesegarray(el):
                parent = el.getparent()
                if parent is not None:
                    parent.remove(el)
        return

    import xml.etree.ElementTree as ET

    root = root_for_parent_map
    if root is None:
        raise ValueError("root_for_parent_map is required for ElementTree edits")
    parent_map = build_parent_map(root)
    for el in list(p.iter()):
        if is_linesegarray(el):
            par = parent_map.get(el)
            if par is not None:
                par.remove(el)


def parse_update_json(path: Path) -> dict:
    data = json.loads(path.read_text(encoding="utf-8"))
    required = [
        "customer",
        "owner_name",
        "window_start",
        "window_end",
        "band",
        "escalation_email",
        "note",
    ]
    missing = [k for k in required if k not in data]
    if missing:
        raise ValueError(f"renewal_update.json missing keys: {missing}")
    return data


def parse_followups_csv(path: Path):
    items = []
    with path.open("r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        if not reader.fieldnames or "sequence" not in reader.fieldnames or "item" not in reader.fieldnames:
            raise ValueError(f"followups.csv must have columns sequence,item; got {reader.fieldnames}")
        for row in reader:
            seq_raw = (row.get("sequence") or "").strip()
            item = (row.get("item") or "").strip()
            if not seq_raw or not item:
                continue
            try:
                seq = int(seq_raw)
            except ValueError as e:
                raise ValueError(f"Invalid sequence '{seq_raw}' in followups.csv") from e
            items.append((seq, item))
    items.sort(key=lambda x: x[0])
    return items


def parse_xml(path: Path):
    raw = path.read_bytes()
    if LXML:
        parser = LXML.XMLParser(remove_blank_text=False, recover=False)
        root = LXML.fromstring(raw, parser=parser)
        return root

    import xml.etree.ElementTree as ET

    # Preserve 'hp' prefix where possible
    ET.register_namespace("hp", HWP_NS)
    root = ET.fromstring(raw)
    return root


def write_xml(path: Path, root):
    if LXML:
        xml_bytes = LXML.tostring(root, encoding="UTF-8", xml_declaration=True, pretty_print=False)
        path.write_bytes(xml_bytes)
        return

    import xml.etree.ElementTree as ET

    tree = ET.ElementTree(root)
    tree.write(path, encoding="UTF-8", xml_declaration=True)


def findall_paragraphs(root):
    if LXML:
        return root.xpath(".//hp:p", namespaces=NSMAP)

    import xml.etree.ElementTree as ET

    return list(root.iter(f"{{{HWP_NS}}}p"))


def update_prefix_fields(root, update_data: dict) -> int:
    """Update paragraphs that start with known labels/prefixes."""
    modified = 0

    for p in findall_paragraphs(root):
        full = paragraph_text(p)
        if not full:
            continue
        if APPENDIX_SENTENCE in full:
            continue

        new_text = None
        if full.startswith("고객사:"):
            new_text = f"고객사: {update_data['customer']}"
        elif full.startswith("현 담당자:"):
            new_text = f"현 담당자: {update_data['owner_name']}"
        elif full.startswith("갱신 윈도우:"):
            new_text = f"갱신 윈도우: {update_data['window_start']} ~ {update_data['window_end']}"
        elif full.startswith("갱신 윈도우 확인:"):
            new_text = f"갱신 윈도우 확인: {update_data['window_start']} ~ {update_data['window_end']}"
        elif full.startswith("가격 메모:"):
            new_text = f"가격 메모: {update_data['note']}"

        if new_text is None or new_text == full:
            continue

        set_paragraph_text_collapsed(p, new_text, root_for_parent_map=root)
        remove_lineseg_cache(p, root_for_parent_map=root)
        modified += 1

    return modified


def _tc_text(tc) -> str:
    """Concatenate all paragraph text under a table cell."""
    parts = []
    if LXML:
        paras = tc.xpath(".//hp:p", namespaces=NSMAP)
    else:
        paras = list(tc.iter(f"{{{HWP_NS}}}p"))
    for p in paras:
        t = paragraph_text(p)
        if t:
            parts.append(t)
    return "".join(parts)


def update_table_fields(root, update_data: dict) -> int:
    modified = 0

    # Find all table rows, interpret first cell as label, second cell as value
    if LXML:
        trs = root.xpath(".//hp:tr", namespaces=NSMAP)
    else:
        trs = list(root.iter(f"{{{HWP_NS}}}tr"))

    for tr in trs:
        if LXML:
            tcs = tr.xpath("./hp:tc", namespaces=NSMAP)
        else:
            tcs = [c for c in list(tr) if localname(c.tag) == "tc"]

        if len(tcs) < 2:
            continue

        label = _tc_text(tcs[0]).strip()
        if not label:
            continue

        target_value = None
        if "가격 밴드" in label:
            target_value = update_data["band"]
        elif "에스컬레이션 연락처" in label:
            target_value = update_data["escalation_email"]

        if target_value is None:
            continue

        # Update first paragraph under the value cell
        if LXML:
            val_paras = tcs[1].xpath(".//hp:p", namespaces=NSMAP)
        else:
            val_paras = list(tcs[1].iter(f"{{{HWP_NS}}}p"))

        if not val_paras:
            continue

        p = val_paras[0]
        full = paragraph_text(p)
        if APPENDIX_SENTENCE in full:
            continue
        if full == target_value:
            continue

        set_paragraph_text_collapsed(p, target_value, root_for_parent_map=root)
        remove_lineseg_cache(p, root_for_parent_map=root)
        modified += 1

    return modified


def update_followups(root, followups_sorted):
    """Replace follow-up paragraphs under the '후속 조치' heading."""
    if not followups_sorted:
        return 0

    modified = 0

    # We need sibling-aware operations: follow-ups are direct <hp:p> children of <hp:section>
    if LXML:
        sections = root.xpath(".//hp:section", namespaces=NSMAP)
    else:
        sections = [root] if localname(root.tag) == "section" else list(root.iter(f"{{{HWP_NS}}}section"))

    for sec in sections:
        # Direct child paragraphs in order
        if LXML:
            children = list(sec)
            paras = [c for c in children if localname(c.tag) == "p"]
        else:
            children = list(sec)
            paras = [c for c in children if localname(c.tag) == "p"]

        # Find heading paragraph exactly '후속 조치'
