def parse_update_json(path: Path) -> dict:
    data = json.loads(path.read_text(encoding="utf-8"))
    required = [
        "customer",
        "owner_name",
        "window_start",
        "window_end",
        "band",
        "escalation_email",
        "note",
    ]
    missing = [k for k in required if k not in data]
    if missing:
        raise ValueError(f"renewal_update.json missing keys: {missing}")
    return data


def parse_followups_csv(path: Path):
    items = []
    with path.open("r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        if not reader.fieldnames or "sequence" not in reader.fieldnames or "item" not in reader.fieldnames:
            raise ValueError(f"followups.csv must have columns sequence,item; got {reader.fieldnames}")
        for row in reader:
            seq_raw = (row.get("sequence") or "").strip()
            item = (row.get("item") or "").strip()
            if not seq_raw or not item:
                continue
            try:
                seq = int(seq_raw)
            except ValueError as e:
                raise ValueError(f"Invalid sequence '{seq_raw}' in followups.csv") from e
            items.append((seq, item))
    items.sort(key=lambda x: x[0])
    return items


def parse_xml(path: Path):
    raw = path.read_bytes()
    if LXML:
        parser = LXML.XMLParser(remove_blank_text=False, recover=False)
        root = LXML.fromstring(raw, parser=parser)
        return root

    import xml.etree.ElementTree as ET

    # Preserve 'hp' prefix where possible
    ET.register_namespace("hp", HWP_NS)
    root = ET.fromstring(raw)
    return root


def write_xml(path: Path, root):
    if LXML:
        xml_bytes = LXML.tostring(root, encoding="UTF-8", xml_declaration=True, pretty_print=False)
        path.write_bytes(xml_bytes)
        return

    import xml.etree.ElementTree as ET

    tree = ET.ElementTree(root)
    tree.write(path, encoding="UTF-8", xml_declaration=True)


def findall_paragraphs(root):
    if LXML:
        return root.xpath(".//hp:p", namespaces=NSMAP)

    import xml.etree.ElementTree as ET

    return list(root.iter(f"{{{HWP_NS}}}p"))


def update_prefix_fields(root, update_data: dict) -> int:
    """Update paragraphs that start with known labels/prefixes."""
    modified = 0

    for p in findall_paragraphs(root):
        full = paragraph_text(p)
        if not full:
            continue
        if APPENDIX_SENTENCE in full:
            continue

        new_text = None
        if full.startswith("고객사:"):
            new_text = f"고객사: {update_data['customer']}"
        elif full.startswith("현 담당자:"):
            new_text = f"현 담당자: {update_data['owner_name']}"
        elif full.startswith("갱신 윈도우:"):
            new_text = f"갱신 윈도우: {update_data['window_start']} ~ {update_data['window_end']}"
        elif full.startswith("갱신 윈도우 확인:"):
            new_text = f"갱신 윈도우 확인: {update_data['window_start']} ~ {update_data['window_end']}"
        elif full.startswith("가격 메모:"):
            new_text = f"가격 메모: {update_data['note']}"

        if new_text is None or new_text == full:
            continue

        set_paragraph_text_collapsed(p, new_text, root_for_parent_map=root)
        remove_lineseg_cache(p, root_for_parent_map=root)
        modified += 1

    return modified


def _tc_text(tc) -> str:
    """Concatenate all paragraph text under a table cell."""
    parts = []
    if LXML:
        paras = tc.xpath(".//hp:p", namespaces=NSMAP)
    else:
        paras = list(tc.iter(f"{{{HWP_NS}}}p"))
    for p in paras:
        t = paragraph_text(p)
        if t:
            parts.append(t)
    return "".join(parts)


def update_table_fields(root, update_data: dict) -> int:
    modified = 0

    # Find all table rows, interpret first cell as label, second cell as value
    if LXML:
        trs = root.xpath(".//hp:tr", namespaces=NSMAP)
    else:
        trs = list(root.iter(f"{{{HWP_NS}}}tr"))

    for tr in trs:
        if LXML:
            tcs = tr.xpath("./hp:tc", namespaces=NSMAP)
        else:
            tcs = [c for c in list(tr) if localname(c.tag) == "tc"]

        if len(tcs) < 2:
            continue

        label = _tc_text(tcs[0]).strip()
        if not label:
            continue

        target_value = None
        if "가격 밴드" in label:
            target_value = update_data["band"]
        elif "에스컬레이션 연락처" in label:
            target_value = update_data["escalation_email"]

        if target_value is None:
            continue

        # Update first paragraph under the value cell
        if LXML:
            val_paras = tcs[1].xpath(".//hp:p", namespaces=NSMAP)
        else:
            val_paras = list(tcs[1].iter(f"{{{HWP_NS}}}p"))

        if not val_paras:
            continue

        p = val_paras[0]
        full = paragraph_text(p)
        if APPENDIX_SENTENCE in full:
            continue
        if full == target_value:
            continue

        set_paragraph_text_collapsed(p, target_value, root_for_parent_map=root)
        remove_lineseg_cache(p, root_for_parent_map=root)
        modified += 1

    return modified


def update_followups(root, followups_sorted):
    """Replace follow-up paragraphs under the '후속 조치' heading."""
    if not followups_sorted:
        return 0

    modified = 0

    # We need sibling-aware operations: follow-ups are direct <hp:p> children of <hp:section>
    if LXML:
        sections = root.xpath(".//hp:section", namespaces=NSMAP)
    else:
        sections = [root] if localname(root.tag) == "section" else list(root.iter(f"{{{HWP_NS}}}section"))

    for sec in sections:
        # Direct child paragraphs in order
        if LXML:
            children = list(sec)
            paras = [c for c in children if localname(c.tag) == "p"]
        else:
            children = list(sec)
            paras = [c for c in children if localname(c.tag) == "p"]

        # Find heading paragraph exactly '후속 조치'
        heading_idx = None
        for idx, p in enumerate(paras):
            if paragraph_text(p).strip() == "후속 조치":
                heading_idx = idx
                break
        if heading_idx is None:
            continue

        # Collect consecutive numbered follow-up paragraphs after heading
        numbered = []
        for p in paras[heading_idx + 1 :]:
            txt = paragraph_text(p).strip()
            if re.match(r"^\d+\.\s+", txt):
                numbered.append(p)
                continue
            # stop at first non-numbered paragraph after we started
            if numbered:
                break

        if not numbered:
            continue

        formatted = [f"{seq}. {item}" for seq, item in followups_sorted]

        # Determine max id in this section to assign ids for new paragraphs
        def _parse_id(p):
            try:
                return int(p.get("id"))
            except Exception:
                return None

        existing_ids = [i for i in (_parse_id(p) for p in paras) if i is not None]
        next_id = (max(existing_ids) + 1) if existing_ids else 1

        # Replace existing paragraphs text for min(len)
        n_common = min(len(numbered), len(formatted))
        for i in range(n_common):
            p = numbered[i]
            if APPENDIX_SENTENCE in paragraph_text(p):
                continue
            if paragraph_text(p) != formatted[i]:
                set_paragraph_text_collapsed(p, formatted[i], root_for_parent_map=root)
                remove_lineseg_cache(p, root_for_parent_map=root)
                modified += 1

        # Remove extra old follow-ups
        if len(numbered) > len(formatted):
            for p in numbered[len(formatted) :]:
                if LXML:
                    sec.remove(p)
                else:
                    sec.remove(p)
                modified += 1

        # Add additional follow-ups
        if len(formatted) > len(numbered):
            template = numbered[-1]
            insert_after = numbered[-1]

            # Find actual index among section children to insert after
            child_list = list(sec)
            try:
                insert_pos = child_list.index(insert_after) + 1
            except ValueError:
                insert_pos = len(child_list)

            for txt in formatted[len(numbered) :]:
                new_p = copy.deepcopy(template)
                # Update id if present
                if new_p.get("id") is not None:
                    new_p.set("id", str(next_id))
                    next_id += 1
                set_paragraph_text_collapsed(new_p, txt, root_for_parent_map=root)
                remove_lineseg_cache(new_p, root_for_parent_map=root)
                sec.insert(insert_pos, new_p)
                insert_pos += 1
                modified += 1

    return modified


def verify_appendix_preserved(root):
    found = False
    for p in findall_paragraphs(root):
        if paragraph_text(p) == APPENDIX_SENTENCE:
            found = True
    return found


def process_contents_xml(xml_path: Path, update_data: dict, followups_sorted):
    root = parse_xml(xml_path)

    before_appendix_ok = verify_appendix_preserved(root)

    modified = 0
    modified += update_prefix_fields(root, update_data)
    modified += update_table_fields(root, update_data)
    modified += update_followups(root, followups_sorted)

    after_appendix_ok = verify_appendix_preserved(root)
    if before_appendix_ok and not after_appendix_ok:
        raise RuntimeError(f"Appendix sentence disappeared or changed in {xml_path}")

    write_xml(xml_path, root)
    return modified


def repack_hwpx(src_hwpx: Path, unpacked_dir: Path, out_hwpx: Path):
    # Preserve original entry order
    with zipfile.ZipFile(src_hwpx, "r") as zin:
        names = zin.namelist()

    if out_hwpx.exists():
        out_hwpx.unlink()

    with zipfile.ZipFile(out_hwpx, "w") as zout:
        for name in names:
            src_path = unpacked_dir / name
            if not src_path.exists():
                raise FileNotFoundError(f"Missing expected unpacked file: {src_path}")
            data = src_path.read_bytes()

            zi = zipfile.ZipInfo(name)
            # Use a stable timestamp to avoid environment variance
            zi.date_time = (2020, 1, 1, 0, 0, 0)
            zi.compress_type = zipfile.ZIP_DEFLATED
            zout.writestr(zi, data)


def main():
    if not SRC_HWPX.exists():
        raise SystemExit(f"Missing {SRC_HWPX}")
    if not UNPACK_DIR.exists():
        raise SystemExit(f"Missing {UNPACK_DIR}; extract the HWPX first")

    update_data = parse_update_json(UPDATE_JSON)
    followups_sorted = parse_followups_csv(FOLLOWUPS_CSV)

    contents_dir = UNPACK_DIR / "Contents"
    xml_files = sorted([p for p in contents_dir.glob("*.xml")])
    if not xml_files:
        raise SystemExit(f"No XML files found under {contents_dir}")

    total_mod = 0
    for xml_path in xml_files:
        mod = process_contents_xml(xml_path, update_data, followups_sorted)
        total_mod += mod
        print(f"updated {xml_path.name}: {mod} paragraph(s) touched")

    repack_hwpx(SRC_HWPX, UNPACK_DIR, OUT_HWPX)
    print(f"Wrote {OUT_HWPX} (total modifications: {total_mod})")


if __name__ == "__main__":
    main()

